<?php
defined( 'ABSPATH' ) || exit;
class CFP_Steps { public static function labels(): array { return array('landing'=>'Landing Page','optin'=>'Optin Page','optin_confirmation'=>'Optin Confirmation','sales'=>'Sales Page','checkout'=>'Checkout Page','order_bump'=>'Order Bump','upsell'=>'One Click Upsell','downsell'=>'Downsell','thank_you'=>'Thank You Page','webinar_registration'=>'Webinar Registration','webinar_replay'=>'Webinar Replay','delivery'=>'Digital Product Delivery Page'); } public function create_pages(int $funnel_id,string $funnel_name,array $steps): void { global $wpdb; $i=0; foreach($steps as $step){ $key=sanitize_key($step); $title=$funnel_name.' - '.(self::labels()[$key]??ucwords(str_replace('_',' ',$key))); $content='<!-- wp:shortcode -->[conversionflow_step type="'.esc_attr($key).'"]<!-- /wp:shortcode -->'; $page_id=wp_insert_post(array('post_type'=>'page','post_status'=>'publish','post_title'=>$title,'post_content'=>$content,'page_template'=>'elementor_canvas'),true); if(is_wp_error($page_id)){ continue; } update_post_meta($page_id,'_cfp_funnel_id',$funnel_id); update_post_meta($page_id,'_cfp_step_type',$key); update_post_meta($page_id,'_wp_page_template','elementor_canvas'); $wpdb->insert(CFP_Database::table('steps'),array('funnel_id'=>$funnel_id,'page_id'=>(int)$page_id,'step_type'=>$key,'title'=>$title,'position'=>$i++,'settings'=>'{}','status'=>'active','created_at'=>current_time('mysql'))); } } }
